import React from 'react';

function Contact({ lang }) {
  return (
    <div>
      <h1>
        {lang === 'ru'
          ? 'Контакты'
          : 'Contacts'}
      </h1>

      <p>+7 908 517 50 43</p>

      <p>
        {lang === 'ru'
          ? 'Телеграм'
          : 'Telegram'}: @teacher_site
      </p>
    </div>
  );
}

export default Contact;
